{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "The closest analogue (Morgan 0.4359) shares the thiophene sulfonamide-isoxazole core and acidic sulfonamide; in humans it showed oral availability >80% in phase I, strongly supporting F≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Pritelivir, a thiophene sulfonamide, showed 75% oral bioavailability in a human dose-escalation trial, supporting high oral bioavailability for this chemotype despite lower structural similarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Stiripentol, which contains the same benzodioxole motif, has absolute oral bioavailability ≥70% in non-elderly adults, indicating the dioxole group is not inherently bioavailability-limiting.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Azosemide, a sulfonamide diuretic, had only ~10% oral bioavailability, but its structural similarity to the query is low and the estimate is based on urinary excretion, providing weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue (0.4359) with the same thiophene sulfonamide-isoxazole core has human oral bioavailability >80%, and other sulfonamide/dioxole-containing analogues are also high (75%, ≥70%). A low-F sulfonamide (azosemide, ~10%) is much less similar and methodologically weaker, so it does not outweigh the direct supportive evidence. Prediction: high.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query molecule.",
    "Closest analogue similarity is moderate (0.4359), not high.",
    "The dioxole group may introduce metabolic liability not captured by the closest analogue.",
    "Physicochemical prior predicts poor passive permeability due to ionization, but direct analogue evidence suggests this may not be decisive."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

